// Facts for OpenTube (repo name: cart pump A, v2). Every number is read from the repository at build time, never typed in here.
// Sources: mechanical/out/cart_a_v2/package_report.json (generated by mechanical/cart_a_v2/package.py) for sizes, volumes and the
// package check; mechanical/CART-A-V2-BRIEF.md for cartridge, stroke, interlock, drive and the Insight reference size.
// A missing source degrades to null values (the page shows "n/a"), never to a failed build.
import { plain, read, tables } from './lib.mjs';

export const OT_REPORT = 'mechanical/out/cart_a_v2/package_report.json';
export const OT_BRIEF = 'mechanical/CART-A-V2-BRIEF.md';
export const OT_SHELLS = 'mechanical/out/cart_a_v2/print/shells_report.json';

const r1 = (n) => (n == null || Number.isNaN(+n) ? null : Math.round(+n * 10) / 10);
const json = (rel) => { try { const s = read(rel); return s ? JSON.parse(s) : null; } catch { return null; } };
const numOf = (re, s) => { const m = re.exec(s ?? ''); return m ? +m[1] : null; };

/** Row of the brief's section-1 table whose item column matches re (cells as plain text). */
function itemRow(brief, re) {
  const t = tables(brief).find((x) => /^item$/i.test(plain(x.headers[1] ?? '')));
  const row = t?.rows.find((r) => re.test(plain(r[1] ?? '')));
  return row ? row.map(plain) : null;
}

export function collectOpenTube() {
  const rep = json(OT_REPORT);
  const brief = read(OT_BRIEF) ?? '';
  const shells = json(OT_SHELLS);
  const S = rep?.size ?? {};
  const warn = [];

  // ---- size: length with the adapter from the report; the adapter sits flush on the 49 x 19 head, so width and height are the head's
  const withAdapter = S.with_adapter_mm ?? null;
  const body = S.body_with_head_mm ?? null;
  const size = withAdapter && body ? { l: r1(withAdapter[0]), w: r1(body[1]), h: r1(body[2]), bodyL: r1(body[0]) } : null;
  const insight = S.insight_mm ? { l: S.insight_mm[0], w: S.insight_mm[1], h: S.insight_mm[2], box: S.insight_box_ml ?? null } : null;
  const envelope = r1(S.total_envelope_ml);
  const vsInsight = S.vs_insight_box ? String(S.vs_insight_box).replace('-', '−').replace(/%$/, ' %') : null;
  const vsPct = S.total_envelope_ml && S.insight_box_ml ? Math.round((S.total_envelope_ml / S.insight_box_ml - 1) * 100) : null;

  // ---- brief: cartridge, stroke, deliverable volume, interlock, drive, Insight reference
  const cartRow = itemRow(brief, /^Cartridge/i);
  const cart = cartRow ? {
    ml: numOf(/([\d.]+)\s*ml/i, cartRow[1]),
    iso: /ISO\s*[\d-]+/i.exec(cartRow[1])?.[0] ?? null,
    od: numOf(/OD\s*([\d.]+)/i, cartRow[1]),
    len: numOf(/([\d.]+)\s*long/i, cartRow[1]),
  } : null;
  const driveRow = itemRow(brief, /^Drive/i);
  const stroke = numOf(/stroke\s*([\d.]+)/i, driveRow?.[2] ?? '');
  const drive = driveRow ? {
    motor: /(NFP-[\w.-]+)\s+gearmotor/i.exec(driveRow[2])?.[1] ?? null,
    pinion: numOf(/pinion\s*z(\d+)/i, driveRow[2]),
    gear: numOf(/gear\s*z(\d+)/i, driveRow[2]),
    screw: /(M\d+(?:\.\d+)?\s*x\s*[\d.]+)\s*screw/i.exec(driveRow[2])?.[1] ?? null,
  } : null;
  const boardRow = itemRow(brief, /main board/i);
  const chips = boardRow ? boardRow[2].replace(/\s*\([^)]*\)/g, '').split(/,\s*/).map((x) => x.trim()).filter(Boolean) : [];
  const deliverable = numOf(/full\s*([\d.]+)\s*ml/i, brief);
  const interlockRow = itemRow(brief, /interlock/i);
  const interlock = /motor only with\s+([^;]+)/i.exec(interlockRow?.[2] ?? '')?.[1]?.trim() ?? null;
  const thrust = /Thrust\s*([\d.]+)\s*N\s*vs\s*([\d.]+)\s*N/i.exec(brief);
  const yokeSaves = numOf(/buys those\s*([\d.]+)\s*mm/i, brief);
  const insightSrc = /Accu-Chek Insight\*\*\s*\(([^)]*)\)/.exec(brief)?.[1] ?? null;
  const manualRef = insightSrc && /user manual[^,)]*/i.exec(insightSrc)?.[0];

  // ---- checks: package (fit + collisions at FULL and EMPTY) and print parts (valid single solids)
  const check = rep ? { pass: !!rep.pass, fit: rep.check?.fit?.length ?? null, collisions: Object.values(rep.check?.collisions ?? {}).reduce((a, x) => a + x.length, 0) } : null;
  const printParts = shells?.parts ? Object.values(shells.parts) : [];
  const shellsOk = printParts.length ? printParts.every((p) => p.valid && p.solids === 1) : null;

  // ---- consistency: the brief's stated size must match the generated report
  const briefL = numOf(/([\d.]+)\s*x\s*49\s*x\s*19 with the adapter/i, brief);
  if (size && briefL && Math.abs(briefL - size.l) > 0.05) warn.push({ doc: OT_BRIEF, what: `states ${briefL} mm with the adapter, the package report gives ${size.l} mm` });
  if (!rep) warn.push({ doc: OT_REPORT, what: 'not found at build time: OpenTube sizes show as n/a' });
  if (!brief) warn.push({ doc: OT_BRIEF, what: 'not found at build time: OpenTube cartridge and drive facts show as n/a' });

  return {
    size, insight, envelope, vsInsight, vsPct, cart, stroke, deliverable, interlock, drive, chips,
    thrust: thrust ? { have: +thrust[1], need: +thrust[2] } : null,
    yokeSaves,
    insightRef: manualRef ?? null, check, shellsOk, printPartCount: printParts.length,
    stale: warn,
  };
}
